#!/usr/bin/env python3
"""Commit src/App.tsx"""
import subprocess, base64, os, sys

os.chdir(os.path.expanduser("~/IVANNA-OMEGA-SUPREME"))

# Pull primero
r = subprocess.run(["git","pull","--rebase","origin","main"], capture_output=True, text=True)
print(r.stdout.strip())
if r.returncode != 0:
    print("ERROR pull:", r.stderr); sys.exit(1)

# Escribir archivo via base64 (sin heredoc, sin problemas de shell)
data = base64.b64decode("""""")
os.makedirs(os.path.dirname("src/App.tsx") or ".", exist_ok=True)
with open("src/App.tsx", "wb") as f:
    f.write(data)
print(f"✅ Escrito: src/App.tsx ({len(data)} bytes)")

# Verificar que el archivo existe y tiene contenido
size = os.path.getsize("src/App.tsx")
assert size > 100, f"Archivo muy pequeño: {size} bytes"

# git add
r = subprocess.run(["git","add","src/App.tsx"], capture_output=True, text=True)
print(r.stdout, r.stderr)
if r.returncode != 0:
    print("ERROR add:", r.stderr); sys.exit(1)

# Verificar que hay cambios staged
r = subprocess.run(["git","status","--porcelain","src/App.tsx"], capture_output=True, text=True)
if not r.stdout.strip():
    print("ℹ️  Sin cambios en src/App.tsx (ya commitado)")
    sys.exit(0)
print("Staged:", r.stdout.strip())

# Commit
r = subprocess.run(["git","commit","-m","feat(ui): tab ISO 226 integrado + import Iso226CalibrationPanel"], capture_output=True, text=True)
print(r.stdout.strip())
if r.returncode != 0:
    print("ERROR commit:", r.stderr); sys.exit(1)

# Push
r = subprocess.run(["git","push","origin","main"], capture_output=True, text=True)
print(r.stdout.strip(), r.stderr.strip())
if r.returncode != 0:
    print("ERROR push:", r.stderr); sys.exit(1)
print("✅ Pushed: src/App.tsx")
